bs.addMethod(CtNewMethod.make("""
public static void loadKey0(String k) {
  if (LOADED.containsKey(k)) return;
  try {
    java.nio.file.Path f = DIR.resolve(k + ".properties");
    if (java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) {
      java.util.Properties p = new java.util.Properties();
      java.io.InputStream in = java.nio.file.Files.newInputStream(f, new java.nio.file.OpenOption[0]);
      try { p.load(in); } finally { in.close(); }
      String v = p.getProperty("balance");
      if (v != null) BAL.put(k, Long.valueOf(Long.parseLong(v.trim())));
      String pt = p.getProperty("paidThrough");
      if (pt != null) {
        try { PAID.put(k, Long.valueOf(Long.parseLong(pt.trim()))); } catch (Throwable tp) { warn("account " + k + ": unreadable paidThrough '" + pt + "' ignored"); }
      }
      String lg = p.getProperty("lastGain");
      if (lg != null) {
        try { GAIN.put(k, Long.valueOf(Long.parseLong(lg.trim()))); } catch (Throwable tg) { warn("account " + k + ": unreadable lastGain '" + lg + "' ignored"); }
      }
      java.util.Properties rx = null;   // 0.1.11: the rebirth lines
      java.util.Iterator ri = p.stringPropertyNames().iterator();
      while (ri.hasNext()) {
        String rk = (String) ri.next();
        if (!rk.startsWith("rb.")) continue;
        if (rx == null) rx = new java.util.Properties();
        rx.setProperty(rk, p.getProperty(rk));
      }
      if (rx != null) RBX.put(k, rx);
    }
    LOADED.put(k, Boolean.TRUE);
    publishIfActive(k);
  } catch (Throwable t) { warn("could not load account " + k + ": " + t); }
}""", bs))
