# 0.1.7 helper: compile a method with @PKG@ / @PR@ / @MSG@ / @UNI@ tokens (the BankPage jv() comes later in this script)
def BX(cls, src):
    s2 = src.replace("@PKG@", PKG).replace("@PR@", PR).replace("@MSG@", MSG).replace("@UNI@", UNI)
    left = re.findall(r"@[A-Z]{2,5}@", s2)
    if left:
        raise SystemExit("unknown token %s in:\n%s" % (left, s2[:300]))
    try:
        cls.addMethod(CtNewMethod.make(s2, cls))
    except Exception as e:
        raise SystemExit("compile failed in %s:\n%s\n---\n%s" % (cls.getName(), e, s2[:1500]))


