# ================= BankPage (0.1.3 logic; 0.1.4 look = the vanilla UI kit tools/skyyui.py; inline, rebuilt only after a click) =================
# Written with @TOKEN@ placeholders instead of f-strings (the markup is full of braces): jv() fills them in.
TOK = {"PKG": PKG, "PR": PR, "REF": REF, "ST": ST, "UCB": UCB, "UEB": UEB, "EVD": EVD, "BT": BT, "LIFE": LIFE,
       "WLD": WLD, "EST": EST, "PLA": PLA, "PGM": PGM, "CPE": CPE, "CPT": CPT, "UNI": UNI, "HSV": HSV}      # 0.1.6: + the page check's
TOKEN = re.compile(r"@([A-Z]{2,5})@")


def jv(src):
    def rep(m):
        k = m.group(1)
        if k not in TOK:
            raise SystemExit("unknown token @%s@ in:\n%s" % (k, src[:300]))
        return TOK[k]
    return TOKEN.sub(rep, src)


def PM(src):
    try:
        page.addMethod(CtNewMethod.make(jv(src), page))
    except Exception as e:
        raise SystemExit("compile failed in BankPage:\n%s\n---\n%s" % (e, jv(src)[:1500]))


page.addField(CtField.make("public String info;", page))
page.addField(CtField.make("public String keepAmount;", page))
# 0.1.6: the click token of the page as last built (the four coin buttons carry it as EventData "t"; null = used up), the build
# counter and a random base per page (tok = hex(base + seq): an older page's tokens never match), the profile key + epoch the page
# was drawn for, when its last packet went out (the check waits SETTLE after it), the world it was opened in, the check state
page.addField(CtField.make("public String tok;", page))
page.addField(CtField.make("public long seq;", page))
page.addField(CtField.make("public long base;", page))
page.addField(CtField.make("public String builtKey;", page))
page.addField(CtField.make("public Object builtEpoch;", page))
page.addField(CtField.make("public volatile long lastSend;", page))
page.addField(CtField.make("public " + WLD + " world;", page))
page.addField(CtField.make("public boolean watching;", page))
page.addField(CtField.make("public volatile boolean dismissed;", page))
page.addField(CtField.make("public String probeNonce;", page))
page.addField(CtField.make("public boolean probeSeen;", page))
page.addField(CtField.make("public int handled;", page))
page.addField(CtField.make("public int heals;", page))
page.addField(CtField.make("public int watchFails;", page))
# a client acknowledges a page packet within a few frames (a local player in well under 100 ms): 1 s later a page answer can no
# longer be waiting, so a test click the engine still drops means the acknowledgements are stuck
page.addField(CtField.make("public static final long SETTLE = 1000L;", page))
page.addConstructor(CtNewConstructor.make(jv(r"""
public BankPage(@PR@ pr) {
  super(pr, @LIFE@.CanDismiss);
  this.info = "";
  this.keepAmount = "";
  this.base = java.util.concurrent.ThreadLocalRandom.current().nextLong() & 0x3fffffffffffffffL;
}"""), page))


# ================= BankWatch part 1 (0.1.6): the page check's timer. EXEC = HytaleServer.SCHEDULED_EXECUTOR (set in setup(), like
# BankTick.WORKER), the ONE shared scheduler thread: a tick there only reads the player's world and hands the check to that world's
# thread (World.execute), where BankPage.watchTick does every PageManager call - the world-thread rule. One check per second per
# open bank page; it ends when the page is closed or replaced (onDismiss / getCustomPage), when the player leaves, or at plugin
# shutdown (STOP). No EXEC (the plugin not set up) = no check, said once a minute in the log.
def WM(src):
    try:
        wat.addMethod(CtNewMethod.make(jv(src), wat))
    except Exception as e:
        raise SystemExit("compile failed in BankWatch:\n%s\n---\n%s" % (e, jv(src)[:1500]))


wat.addInterface(pool.get("java.lang.Runnable"))
wat.addField(CtField.make("public static volatile boolean STOP = false;", wat))
wat.addField(CtField.make("public static final long PERIOD = 1000L;", wat))
wat.addField(CtField.make("public static volatile java.util.concurrent.ScheduledExecutorService EXEC;", wat))
wat.addField(CtField.make("public static volatile long WARNED = 0L;", wat))
wat.addField(CtField.make("public " + PKG + ".BankPage page;", wat))
wat.addField(CtField.make("public " + WLD + " target;", wat))
wat.addConstructor(CtNewConstructor.make(jv(r"""
public BankWatch(@PKG@.BankPage page, @WLD@ target) {
  this.page = page;
  this.target = target;
}"""), wat))
# target == null: the scheduler-thread tick; target != null: the check on that world's thread
WM(r"""
public static void schedule(@PKG@.BankPage page) {
  if (STOP || page == null || page.dismissed) return;
  java.util.concurrent.ScheduledExecutorService ex = EXEC;
  try {
    if (ex == null) throw new java.lang.IllegalStateException("no scheduler (SkyyBank not set up)");
    ex.schedule(new @PKG@.BankWatch(page, (@WLD@) null), PERIOD, java.util.concurrent.TimeUnit.MILLISECONDS);
  } catch (Throwable t) {
    long now = System.currentTimeMillis();
    if (now - WARNED >= 60000L) {
      WARNED = now;
      @PKG@.BankStore.warn("the bank page check could not be scheduled (" + t + ") - a click the game drops is not answered on this page");
    }
  }
}""")
# one string value out of the page event JSON (SkyySacks 0.7.3 CraftPage.jsonStr / SkyyGuilds 0.1 GuildPage.jsonStr, verbatim)
PM(r"""
public static String jsonStr(String data, String key) {
  if (data == null || key == null) return "";
  String qt = String.valueOf((char) 34);
  int i = data.indexOf(qt + key + qt);
  if (i < 0) return "";
  i = data.indexOf(':', i + key.length() + 2);
  if (i < 0) return "";
  i++;
  while (i < data.length() && Character.isWhitespace(data.charAt(i))) i++;
  if (i >= data.length() || data.charAt(i) != 34) return "";
  i++;
  StringBuilder sb = new StringBuilder();
  while (i < data.length() && sb.length() < 200) {
    char c = data.charAt(i);
    if (c == 34) break;
    if (c == 92 && i + 1 < data.length()) {
      char n = data.charAt(i + 1);
      if (n == 'u' && i + 5 < data.length()) {
        try { sb.append((char) Integer.parseInt(data.substring(i + 2, i + 6), 16)); } catch (Throwable t) { }
        i += 6;
        continue;
      }
      if (n == 'n' || n == 'r' || n == 't' || n == 'b' || n == 'f') sb.append(' '); else sb.append(n);
      i += 2;
      continue;
    }
    sb.append(c);
    i++;
  }
  return sb.toString();
}""")
# 12345678 -> "12,345,678" (no Locale: the same separator for every player)
PM(r"""
public static String fmt(long n) {
  boolean neg = n < 0L;
  String s = String.valueOf(neg ? -n : n);
  StringBuilder sb = new StringBuilder();
  int c = 0;
  for (int i = s.length() - 1; i >= 0; i--) {
    sb.append(s.charAt(i));
    c++;
    if (c % 3 == 0 && i > 0) sb.append(',');
  }
  if (neg) sb.append('-');
  return sb.reverse().toString();
}""")
