# 2475000 ms -> "41 min 15 s"; 7500000 -> "2 h 5 min"
PM(r"""
public static String dur(long ms) {
  long s = (ms + 999L) / 1000L;
  if (s < 1L) s = 1L;
  long h = s / 3600L;
  long m = (s % 3600L) / 60L;
  long sec = s % 60L;
  if (h > 0L) return h + " h " + m + " min";
  if (m > 0L) return m + " min " + sec + " s";
  return sec + " s";
}""")
