def bank_outer(mk):
    """(outer width, outer height) of a markup's ROOT element, read from its own Anchor: Width + Left + Right (+ 2 x Horizontal /
    Full) and Height + Top + Bottom (+ 2 x Vertical / Full); None where the root sets no Width / Height. KIT-GAP (review 2): the
    kit builders do not report their outer size, so the budget reads it back out of the markup instead of typing "+ 12" by hand."""
    r = SUI.render(mk)
    i = r.index("{")
    j = r.find("{", i + 1)
    own = r[i + 1:] if j < 0 else r[i + 1:j]
    m = re.search(r"Anchor: \(([^)]*)\)", own)
    a = dict((k, int(v)) for k, v in re.findall(r"(Width|Height|Left|Right|Top|Bottom|Horizontal|Vertical|Full): (-?\d+)",
                                                 m.group(1))) if m else {}
    hm = a.get("Left", 0) + a.get("Right", 0) + 2 * (a.get("Horizontal", 0) + a.get("Full", 0))
    vm = a.get("Top", 0) + a.get("Bottom", 0) + 2 * (a.get("Vertical", 0) + a.get("Full", 0))
    return (a["Width"] + hm if "Width" in a else None), (a["Height"] + vm if "Height" in a else None)


def bank_filled(ap, parent, axis, avail, what, cross=None):
    """Assert that the direct children of `parent` fill it exactly: their outer widths (axis "w", a LayoutMode Left row) or outer
    heights (axis "h", a LayoutMode Top column) sum to `avail` px (no FlexWeight filler); cross = the row height every child of a
    Left row must fit in."""
    kids = [bank_outer(mk) for p, mk in ap if p == parent]
    assert kids, "%s has no children" % what
    sizes = [k[0] if axis == "w" else k[1] for k in kids]
    assert None not in sizes, "%s: a child without a fixed %s" % (what, "Width" if axis == "w" else "Height")
    left = SUI.fit(sizes, avail, what)
    assert left == 0, "%s must be filled exactly: %s = %d of %d px" % (what, sizes, sum(sizes), avail)
    if cross is not None:
        assert all(k[1] is not None and k[1] <= cross for k in kids), "%s: a child is taller than the %d px row: %s" % (what, cross, kids)


def bank_anchor(mk):
    """0.1.5: {Width / Height / Left / Right / Top / Bottom / ...: int} of a markup's ROOT element, read from its own Anchor (the
    same reading as bank_outer)."""
    r = SUI.render(mk)
    i = r.index("{")
    j = r.find("{", i + 1)
    own = r[i + 1:] if j < 0 else r[i + 1:j]
    m = re.search(r"Anchor: \(([^)]*)\)", own)
    return dict((k, int(v)) for k, v in re.findall(r"(Width|Height|Left|Right|Top|Bottom|Horizontal|Vertical|Full): (-?\d+)",
                                                   m.group(1))) if m else {}


def bank_spans(ap, row):
    """0.1.5: [(id or None, x0, x1)] - where each direct child of the LayoutMode Left row `row` sits (Left margin + Width, then its
    Right margin), read back out of the markup: proves the captions sit exactly under their controls."""
    out, x = [], 0
    for p, mk in ap:
        if p != row:
            continue
        a = bank_anchor(mk)
        mt = re.match(r"\s*[A-Za-z]+(?:\s+#([A-Za-z0-9]+))?\s*\{", SUI.render(mk))
        x0 = x + a.get("Left", 0)
        out.append((mt.group(1), x0, x0 + a["Width"]))
        x = x0 + a["Width"] + a.get("Right", 0)
    return out


def bank_page():
    """(shell, sets): BankPage's markup from the kit - 0.1.4's page with the controls row reordered (Skyy: the amount box between
    Deposit and Withdraw) and every size x 1.1 (bank_px). The page height is still the sum of its parts (the body, every row and
    every well filled exactly, read back out of the markup), the captions sit under their controls, every button label fits, every
    margin is a vanilla step x 1.1, only proven properties - asserted, like every 0.1.3 id and b.set target."""
    # 0.1.16 MENU PATTERN: the kit 1.7 hub page (1600 x 980: title bar, row 1, row 2, the content); the 0.1.3 root #SkyyBank is the CONTENT
    # group now, 0.1.12's 1173 px column centred in it; the 577 px of 0.1.15's parts sit centred on the content's height (a spacer above
