    assert (sh.w, sh.h, sh.content_w, old_h) == (1600, 980, 1173, 577) and sh.content_h >= old_h, "0.1.16: the bank content fits the hub page"
    ap, body, W = sh.appends, sh.content, sh.content_w
    pad_top = (sh.content_h - old_h) // 2
    ap.append((body, SUI.spacer(h=pad_top)))
    n_frame = len(ap)
    m = bank_px                           # 0.1.4's size -> 0.1.5's (x 1.1)
    FS = BANK_FS
    BTN, WIDE, BH, BSZ = BANK_BTN, BANK_BTN_WIDE, BANK_BTN_H, BANK_BTN_SIZE
